def sha256_file(path: Path) -> str:
    h = hashlib.sha256()
    with path.open("rb") as f:
        for block in iter(lambda: f.read(8 << 20), b""):
            h.update(block)
    return h.hexdigest()


def write_json(path: Path, payload: dict) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_suffix(path.suffix + ".tmp")
    tmp.write_text(json.dumps(payload, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    tmp.replace(path)


def load_json(path: Path) -> dict:
    return json.loads(path.read_text(encoding="utf-8"))


def check_file(path: Path, expected_sha: str, expected_bytes: int | None = None) -> None:
    if not path.is_file():
        raise RuntimeError(f"MISSING_FILE:{path}")
    if expected_bytes is not None and path.stat().st_size != expected_bytes:
        raise RuntimeError(f"SIZE_DRIFT:{path}:{path.stat().st_size}!={expected_bytes}")
    got = sha256_file(path)
    if got != expected_sha:
        raise RuntimeError(f"SHA256_DRIFT:{path}:{got}!={expected_sha}")


def run(cmd: list[str], *, cwd: Path, env: dict[str, str]) -> None:
    print("+", " ".join(cmd), flush=True)
    subprocess.run(cmd, cwd=str(cwd), env=env, check=True)


def ensure_linux_authority_root() -> None:
    # The Stage08 evidence is exact-path bound to /home/runner/realsas_authority.
    # Refuse to silently remap it: remapping would change upstream authority hashes.
    try:
        AUTHORITY_ROOT.mkdir(parents=True, exist_ok=True)
        probe = AUTHORITY_ROOT / ".realsas_write_probe"
        probe.write_text("ok\n", encoding="utf-8")
        probe.unlink()
    except PermissionError as exc:
        raise RuntimeError(
            "EXACT_PATH_BINDING_REQUIRES_WRITE_ACCESS:/home/runner/realsas_authority. "
            "Run this continuation inside WSL/Linux with permission to create /home/runner."
        ) from exc


def download_exact(url: str, dest: Path, expected_sha: str, expected_bytes: int) -> None:
    if dest.is_file():
        try:
            check_file(dest, expected_sha, expected_bytes)
            return
        except RuntimeError:
            dest.unlink()
    dest.parent.mkdir(parents=True, exist_ok=True)
    print(f"DOWNLOAD {url} -> {dest}", flush=True)
    with urllib.request.urlopen(url, timeout=120) as response, dest.open("wb") as out:
        shutil.copyfileobj(response, out)
    check_file(dest, expected_sha, expected_bytes)


def extract_exact(zip_path: Path, dest: Path) -> None:
    dest.mkdir(parents=True, exist_ok=True)
    with zipfile.ZipFile(zip_path) as z:
        z.extractall(dest)


def copy_tree_exact(src: Path, dst: Path) -> None:
    if dst.exists():
        shutil.rmtree(dst)
    shutil.copytree(src, dst)


def ledger_stage(repo: Path, stage_id: str) -> dict:
    ledger = load_json(repo / "canonical" / "ACTIVE_RUN_V1.json")
    return next(row for row in ledger["stages"] if row["id"] == stage_id)


def require_stage_pass(repo: Path, stage_id: str) -> dict:
    row = ledger_stage(repo, stage_id)
    if row.get("status") not in {"PASS", "CACHE_HIT"}:
        raise RuntimeError(f"STAGE_NOT_PASS:{stage_id}:{row.get('status')}")
    return row


